176	  // Season ordering and material relief both live in `eligibleByCategory`, so
177	  // this function, `eligibility` and `missingCategory` can never disagree about
178	  // what the closet can do. Ordering in-season-first matters because the CAP
179	  // below truncates the combo list, and the breadth-first walk indexes outerwear
180	  // and accessories modulo their list length — so the earliest passes reach the
181	  // seasonally right coat and accessory.
182	  const by = eligibleByCategory(items, a);
183	  const tops = by.Tops ?? [];
184	  const bottoms = by.Bottoms ?? [];
185	  const shoes = by.Shoes ?? [];
186	  const outer = by.Outerwear ?? [];
187	  const accessories = by.Accessories ?? [];
188	
189	  // A combo needs all three required slots; without one there is nothing to build.
190	  if (!tops.length || !bottoms.length || !shoes.length) return [];
191	
192	  const combos: CandidateItem[][] = [];
193	
194	  // BREADTH-FIRST, not a nested product.
195	  //
196	  // This used to be three nested loops followed by `.slice(0, CAP)`. Because the
197	  // loops were top-major, every combination of the FIRST top was generated
198	  // before the second top was reached — so the cap was spent inside one top. A
199	  // closet with 20 of each category reached 1 top and 5 bottoms out of 20, which
200	  // is both reported symptoms at once: most of the wardrobe invisible to
