202	  // share. Small closets stayed under the cap, which is why tests never saw it.
203	  //
204	  // Each pass `d` walks all tops once, pairing each with a different bottom and
205	  // shoe, so pass 0 alone touches every top, bottom and shoe. Later passes add
206	  // fresh pairings rather than exhausting one corner of the space. The shoe
207	  // offset uses a stride coprime with the shoe count so pairings do not repeat
208	  // early AND every shoe is still reachable — a fixed stride of 2 failed the
209	  // second half of that on any even-length list (see `decorrelatedStride`).
210	  const passes = Math.max(bottoms.length, shoes.length);
211	  const shoeStride = decorrelatedStride(shoes.length);
212	
213	  build: for (let d = 0; d < passes; d++) {
214	    for (let t = 0; t < tops.length; t++) {
215	      const b = bottoms[(t + d) % bottoms.length];
216	      const s = shoes[(t + d * shoeStride) % shoes.length];
