26	export function laterAdvice(
27	  hourly: HourCell[],
28	  unit: TempUnit = "C",
29	  dayHighC?: number,
30	): { sentence: string; adviceClause: string } {
31	  const rainHour = hourly.find((h) => h.rain);
32	  if (rainHour) {
33	    const adviceClause = "take a shell.";
34	    return { sentence: `Rain from ${rainHour.hh} — ${adviceClause}`, adviceClause };
35	  }
36	
37	  const now = hourly[0]?.tempC ?? 0;
38	
