40	  // will look lighter than the thermometer currently justifies. Say so — this
41	  // sentence is the ONLY thing that explains why, and without it a light outfit
42	  // at 20°C reads as the stylist getting it wrong. It is also the other half of
43	  // the decision: dress for the peak, and be told about the cool start.
44	  if (dayHighC != null && dayHighC - now >= RISE_C) {
45	    const adviceClause = "you're dressed for it.";
46	    return {
47	      sentence: `Up to ${formatTemp(dayHighC, unit)} this afternoon — ${adviceClause}`,
48	      adviceClause,
49	    };
50	  }
51	
