42	export async function generate(input: {
43	  occasion: UiOccasion;
44	  formality: number | null;
45	  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
46	  lean: string[];
47	  /** Explicit user action only — the one way to spend an AI call on a day already answered. */
48	  regenerate?: boolean;
49	  city?: { lat: number; lon: number; label: string; source: LocationSource };
50	}): Promise<GenerateResult> {
51	  try {
52	    const supabase = await createClient();
53	    const {
54	      data: { user },
55	    } = await supabase.auth.getUser();
56	    if (!user) return { status: "error", message: "Not signed in" };
57	
58	    const { data: profile } = await supabase
59	      .from("profiles")
60	      .select(
61	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source, preferences",
62	      )
63	      .eq("id", user.id)
64	      .single();
65	    const { data: itemsRaw } = await supabase
66	      .from("items")
67	      .select("*")
68	      .eq("user_id", user.id)
69	      .eq("archived", false);
70	    const items = itemsRaw ?? [];
71	    const byId = new Map(items.map((i) => [i.id, i]));
72	    const pathFor = (id: string) => {
73	      const it = byId.get(id);
74	      return it ? displayPath(it) : undefined;
75	    };
76	
77	    const loc = resolveLocation({ input: input.city, profile });
78	
79	    const now = new Date();
80	    const f = await fetchForecast(loc.lat, loc.lon);
81	    const prefs = readPreferences(profile?.preferences);
82	    const advice = laterAdvice(f.hourly, prefs.tempUnit, f.highC);
83	    const weather: WeatherPayload = {
84	      tempC: f.tempC,
85	      feelsLikeC: f.feelsLikeC,
86	      condition: f.condition,
87	      cityLabel: loc.label,
88	      timezone: f.timezone,
89	      locationOrigin: loc.origin,
90	      laterSentence: advice.sentence,
91	      adviceClause: advice.adviceClause,
92	      laterLabel: "Later",
93	      hourly: f.hourly,
94	      tempUnit: prefs.tempUnit,
95	    };
96	
97	    const today = localDateFor(now, f.timezone);
98	
99	    // The daily drop (Decision 5): today's looks are generated once and then
100	    // read back. Only an explicit regenerate spends an AI call on a day the
101	    // stylist has already answered.
102	    //
103	    // The stored set is read on BOTH paths. On a normal load it IS the answer;
104	    // on a regenerate it is the recency signal — the pieces the user just
105	    // rejected, which ranking will sink without ever filtering them out.
106	    const stored = await loadDailyLooks(user.id, input.occasion, today);
107	
108	    /**
109	     * Today's looks were composed for wherever the user was when they were
110	     * generated. Moving invalidates them: Decision 5 caches the drop, but
111	     * caching does not make a 26°C Manila outfit correct under a 12°C
112	     * Reykjavik sky.
113	     *
114	     * INTENT decides, not distance: a deliberate city pick always rebuilds,
115	     * however near, because the user asked and a screen that does not change
116	     * reads as broken. A silent GPS refresh only rebuilds past 25km, so a
117	     * commute does not cost a generation. See `invalidatesDrop`.
118	     *
119	     * Falling through here is deliberately how this is implemented: the block
120	     * below already records a fall-through as a `drop`, never a `regenerate`,
121	     * so the rebuild is free on every tier. The user changed where they are;
122	     * they did not ask for another look.
123	     *
124	     * The Settings path clears the stored rows outright in `setLocation`. This
125	     * covers the OTHER door — the Stylist's weather pill, which writes through
126	     * `saveLocation` AFTER this action has already run, and so cannot clear
127	     * anything without deleting the looks this very call just stored.
128	     */
129	    const movedAway = input.city
130	      ? invalidatesDrop(input.city, resolveLocation({ profile }))
131	      : false;
132	
133	    if (!input.regenerate && !movedAway && stored?.length) {
134	      const paths = Array.from(
135	        new Set(
136	          stored
137	            .flatMap((s) => s.pieces.map((p) => byId.get(p.itemId)))
138	            .filter((it): it is NonNullable<typeof it> => Boolean(it))
139	            .map((it) => displayPath(it)),
140	        ),
141	      );
142	      const signed = await signItemImages(paths);
143	      const looks = reassembleLooks(stored, byId, signed, pathFor);
144	      // null = the closet changed under the stored set; fall through and
145	      // regenerate rather than showing an outfit with a hole in it.
146	      if (looks) return { status: "ok", weather, looks };
147	    }
148	
149	    // Only a deliberate regenerate carries the signal. A fall-through from a
150	    // stale stored set is the app fixing itself, not the user asking for
151	    // something else — penalising those pieces would be arbitrary.
152	    const recentlyShown = input.regenerate
153	      ? Array.from(new Set(stored?.flatMap((s) => s.pieces.map((p) => p.itemId)) ?? []))
154	      : [];
155	
156	    /**
157	     * A fall-through is a DROP, not a regenerate.
158	     *
159	     * Reaching here without `input.regenerate` means either the occasion has no
160	     * looks today, or the stored set no longer reassembles because the closet
161	     * changed under it. Both are the app answering for the first time or
162	     * repairing its own bookkeeping — not the user asking again — and neither
163	     * should be charged. Drops are free on every tier regardless, so the
164	     * distinction only matters for what the ledger records.
165	     */
166	    const gen: GenerationRequest = {
167	      kind: input.regenerate ? "regenerate" : "drop",
168	      occasion: input.occasion,
169	      today,
170	    };
171	    // Caught HERE rather than in the outer catch, for two reasons: `weather` is
172	    // in scope so the screen keeps its strip instead of collapsing, and being
173	    // limited is a STATE, not a failure — routing it through the error path
174	    // would render "Couldn't reach the stylist" for a working app.
175	    try {
176	      await assertCanGenerate(user.id, gen);
177	    } catch (e) {
178	      if (e instanceof QuotaExceededError) {
179	        return { status: "limited", weather, message: e.message };
180	      }
181	      throw e;
182	    }
183	
184	    const candItems: CandidateItem[] = items.map((i) => ({
185	      id: i.id,
186	      category: i.category,
187	      colors: i.colors ?? [],
188	      formality: i.formality,
189	      seasons: i.seasons ?? [],
190	      material: i.material,
191	      texture: i.texture,
192	      pattern: i.pattern,
193	    }));
194	    // Occasion gives the context; the user's onboarding dress codes narrow it;
195	    // an explicit Refine formality overrides both.
196	    const band = applyFormalityOverride(
197	      personalBand(input.occasion, profile),
198	      input.formality,
199	    );
200	    const candidateArgs = {
201	      band,
202	      weather: {
203	        tempC: f.tempC,
204	        rain: f.hourly.some((h) => h.isNow && h.rain),
205	        // The look is built for the day, not for this minute.
206	        highC: f.highC,
207	        lowC: f.lowC,
208	      },
209	      season: currentSeason(now),
210	      excludeItemIds: [],
211	      maxAccessories: 1,
212	      rainGuard: prefs.rainGuard,
213	    };
214	    const combos = buildCandidates(candItems, candidateArgs);
215	    if (combos.length === 0) {
216	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
217	    }
218	
219	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
220	    // The Refine colour pick lands here, in ranking — not in candidate building.
221	    // It reorders the shortlist toward the requested families and is dropped
222	    // silently when the closet cannot honour it.
223	    //
224	    // Rank everything, then spread the shortlist across the wardrobe before the
225	    // re-ranker sees it. Taking the top 20 by score alone clusters — a neutral
226	    // top harmonises with everything, so it occupies most of the list, and "the
227	    // best 3" of a clustered list is three versions of one outfit. Diversifying
228	    // the INPUT makes the model's three distinct by construction.
229	    // Season rides along as a ranking preference — in-season combos float to the
230	    // top of the shortlist the re-ranker sees, but an off-season one is still
231	    // offered rather than the screen going empty.
232	    const ranked = rankTopN(
233	      combos,
234	      {
235	        aesthetic,
236	        band,
237	        lean: input.lean,
238	        recentlyShown,
239	        season: candidateArgs.season,
240	        // The day's high, not the current reading — the drop is generated once
241	        // and worn all day. `planningTemp` is the single definition of that.
242	        tempC: planningTemp(candidateArgs.weather),
243	      },
244	      combos.length,
245	    );
246	    const top = diversify(ranked, 20);
247	
248	    // A look the user has already worn today is PINNED: saveDailyLooks leaves it
249	    // in place, so it has to survive in what we hand back to the screen too —
250	    // otherwise the day's set silently loses it until the next page load. It
251	    // also still COUNTS toward the day's three, so the stylist is asked for
252	    // fewer fresh looks rather than the set growing a fourth tab.
253	    const pinnedStored = (stored ?? []).filter((s) => s.worn);
254	
255	    const { picks } = await rerank({
256	      want: MAX_PICKS - pinnedStored.length,
257	      combos: top.map((t) =>
258	        t.items.map((ci) => {
259	          const it = byId.get(ci.id)!;
260	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
261	        }),
262	      ),
263	      aesthetic,
264	      occasion: input.occasion,
265	      weatherLabel: f.condition,
266	      tempC: f.tempC,
267	    });
268	
269	    const paths = Array.from(
270	      new Set([
271	        ...top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!))),
272	        ...pinnedStored.flatMap((s) =>
273	          s.pieces.map((p) => pathFor(p.itemId)).filter((p): p is string => Boolean(p)),
274	        ),
275	      ]),
276	    );
277	    const signed = await signItemImages(paths);
278	
279	    // `rerank` already dropped picks that repeat a combo or point outside the
280	    // shortlist, so every index here resolves. It previously fell back to
281	    // `top[0]` for an unknown index, which turned a bad index into a duplicate
282	    // of the first look rather than into one fewer look.
283	    const drafts: LookDraft[] = picks.map((p) => {
284	      const combo = top[p.combo_index].items;
285	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
286	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
287	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
288	        itemId: d.id,
289	        category: d.category,
290	        subcategory: d.subcategory ?? null,
291	        brand: d.brand ?? null,
292	        name: d.name ?? null,
293	        colors: d.colors ?? [],
294	        cutoutUrl: signed.get(displayPath(d)) ?? "",
295	        slot: slots[idx],
296	      }));
297	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
298	    });
299	
300	    // Fire-and-forget would be simpler, but a failed write means the user pays
301	    // for another AI call on their next tap — worth awaiting. The insert also
302	    // hands back the row ids, which are the detail screen's address.
303	    const ids = await saveDailyLooks(user.id, input.occasion, today, weather, drafts);
304	    const fresh: Look[] = drafts.map((d, i) => ({ ...d, id: ids[i] ?? "", worn: false }));
305	
306	    // Recorded only now — after the model answered and the write succeeded. A
307	    // generation that failed cost the user nothing, so metering it would be
308	    // charging them for our error.
309	    await noteGeneration(user.id, gen);
310	
311	    // Pinned looks keep their place at the front — they hold the lower
312	    // look_index values, which is the order the next load will read them back in.
313	    const pinned = reassembleLooks(pinnedStored, byId, signed, pathFor) ?? [];
314	
315	    return { status: "ok", weather, looks: [...pinned, ...fresh] };
316	  } catch (e) {
317	    console.error("[generate] failed:", e);
318	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
319	  }
320	}
