322	/**
323	 * The single write path for a user's location. `generate` stays read-only.
324	 * Called by the client after a successful generate for a location the user
325	 * actually supplied (geolocation or city search) — never for the profile or
326	 * default fallback, where there is nothing new to write.
327	 */
328	export async function saveLocation(input: unknown): Promise<void> {
329	  const d = LocationInputSchema.parse(input);
330	
331	  const supabase = await createClient();
332	  const {
333	    data: { user },
334	  } = await supabase.auth.getUser();
335	  if (!user) return;
336	
337	  await supabase
338	    .from("profiles")
339	    .update(locationColumns(d, new Date().toISOString()))
340	    .eq("id", user.id);
341	}
