343	/**
344	 * The seed for the morning. Cheap on purpose — one profile read, date math, NO
345	 * AI and NO weather — so the client can pick the right occasion before the first
346	 * generate without adding latency.
347	 */
348	export async function predictDefaultOccasion(): Promise<{ occasion: UiOccasion; reason: string }> {
349	  const supabase = await createClient();
350	  const {
351	    data: { user },
352	  } = await supabase.auth.getUser();
353	  if (!user) return { occasion: "everyday", reason: defaultReason("everyday") };
354	
355	  const { data: profile } = await supabase
356	    .from("profiles")
357	    .select("occasions, location_timezone")
358	    .eq("id", user.id)
359	    .single();
360	
361	  const tz = profile?.location_timezone ?? "UTC";
362	  const occasion = predictOccasion(new Date(), tz, profile?.occasions ?? []);
363	  return { occasion, reason: defaultReason(occasion) };
364	}
