366	/**
367	 * Record that the user chose an occasion other than the predicted default.
368	 * Fire-and-forget: the caller does not await the outcome, and a failure here
369	 * must never affect the looks. Guards `chosen === predicted` so a no-op tap is
370	 * not logged as an override.
371	 */
372	export async function logOccasionOverride(input: {
373	  predicted: UiOccasion;
374	  chosen: UiOccasion;
375	}): Promise<void> {
376	  if (input.chosen === input.predicted) return;
377	
378	  const supabase = await createClient();
379	  const {
380	    data: { user },
381	  } = await supabase.auth.getUser();
382	  if (!user) return;
383	
384	  const { data: profile } = await supabase
385	    .from("profiles")
386	    .select("location_timezone")
387	    .eq("id", user.id)
388	    .single();
389	
390	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
391	  await recordOverride(user.id, today, input.predicted, input.chosen);
392	}
